"use strict";(globalThis.webpackChunkconduction_website=globalThis.webpackChunkconduction_website||[]).push([[6620],{68464(e,n,t){t.r(n),t.d(n,{assets:()=>s,contentTitle:()=>d,default:()=>u,frontMatter:()=>i,metadata:()=>a,toc:()=>l});var a=t(94474),r=t(74848),o=t(28453);const i={slug:"the-platform-moment",title:"Nextcloud is een platform",contentType:"opinion",authors:["ruben"],date:new Date("2026-05-19T00:00:00.000Z"),summary:"Een opiniestuk over waarom Nextcloud bekeken zou moeten worden als een platform, niet als een product. De sovereign-workplace-bundels zijn het begin, niet het einde. Microsoft heeft achttien tot zesendertig maanden. Europa ook.",tags:["Nextcloud","Platform","Sovereignty","AI"],durationMinutes:7},d=void 0,s={authorsImageUrls:[void 0]},l=[{value:"Het patroon",id:"het-patroon",level:2},{value:"Waarom Nextcloud op deze positie zit",id:"waarom-nextcloud-op-deze-positie-zit",level:2},{value:"De bundel is niet de werkplek",id:"de-bundel-is-niet-de-werkplek",level:2},{value:"AI als substraat, niet als vinkje",id:"ai-als-substraat-niet-als-vinkje",level:2},{value:"De Microsoft-klok",id:"de-microsoft-klok",level:2},{value:"Wat waar moet zijn",id:"wat-waar-moet-zijn",level:2},{value:"Een persoonlijke noot",id:"een-persoonlijke-noot",level:2}];function p(e){const n={a:"a",h2:"h2",p:"p",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.p,{children:"Hetzelfde patroon duikt op elke keer dat een softwarecategorie door zijn platformmoment heen gaat. WordPress in 2011. Salesforce een paar jaar eerder. Atlassian daarna. De iPhone, in de consumentenmarkt, v\xf3\xf3r allemaal. Elk van hen begon als product. Elk werd een platform. De bedrijven die de overgang goed managen, bezitten hun categorie twee decennia later. De bedrijven die dat niet deden, zijn voetnoten."}),"\n",(0,r.jsx)(n.p,{children:"Ik denk dat Nextcloud nu vlak voor die overgang staat, en ik denk dat het veld eromheen het nog niet doorheeft."}),"\n","\n",(0,r.jsx)(n.h2,{id:"het-patroon",children:"Het patroon"}),"\n",(0,r.jsx)(n.p,{children:"Wat een product tot een platform maakt, is geen feature release. Het is een herframing."}),"\n",(0,r.jsx)(n.p,{children:"WordPress core bleef bewust klein, terwijl het plugin-ecosysteem uitgroeide tot een miljardenmarkt. De plugin-laag werd het eigenlijke product. WordPress core werd infrastructuur. Tegen 2020 kon je niets anders kiezen voor iets anders dan enterprise-CMS of proprietary SaaS \u2014 niet omdat WordPress op features had gewonnen, maar omdat het ecosysteem eromheen had gewonnen."}),"\n",(0,r.jsx)(n.p,{children:"Salesforce AppExchange verscheen in 2006. Eind jaren tien gebruikte 91% van de Salesforce-klanten minstens \xe9\xe9n app eruit. D\xe1t is de echte gracht onder het bedrijf. Concurrenten hoeven niet alleen de CRM te verslaan. Ze moeten de CRM plus zesduizend integraties verslaan. De AppExchange-partners verdienen samen een veelvoud van wat Salesforce zelf direct uit de marktplaats verdient. Beide winnen in dezelfde uitkomst."}),"\n",(0,r.jsx)(n.p,{children:'De iPhone won smartphones niet door een betere telefoon te zijn. Hij won door te worden uitgeroepen tot "het platform dat apps draait" voordat dat technisch waar was. Tegen 2010 kopieerde elk ander platform het App Store-model, of het verdween. De naamgeving liep jaren vooruit op de platformrealiteit. Die naamgeving was dragend.'}),"\n",(0,r.jsx)(n.p,{children:"SharePoint is de waarschuwende casus. Microsoft positioneerde het tien jaar lang als h\xe9t platform. Het technische oppervlak ondersteunde dat. Het marketingbudget ondersteunde dat. De architectuur en de economie deden dat niet. SharePoint heeft nooit een ecosysteem voortgebracht. Het bleef een product. Power Platform verdrong het als Microsofts gepositioneerde platform voor businessapps."}),"\n",(0,r.jsx)(n.p,{children:"Vijf casussen. E\xe9n patroon. Telkens dezelfde vorm."}),"\n",(0,r.jsx)(n.h2,{id:"waarom-nextcloud-op-deze-positie-zit",children:"Waarom Nextcloud op deze positie zit"}),"\n",(0,r.jsx)(n.p,{children:"Het substraat voor een werkplek-platform zit vandaag al in Nextcloud Hub. Het wordt alleen niet als substraat geframed."}),"\n",(0,r.jsx)(n.p,{children:"Bestanden. Agenda. Contacten. Talk. Mail. Een identity-laag die al LDAP, SAML en OIDC spreekt. Een permissiemodel dat over al die onderdelen heen werkt. Elke businessapp heeft deze primitieven nodig. Nextcloud levert ze al ge\xefntegreerd, in \xe9\xe9n product, met \xe9\xe9n toegangsbeheer-oppervlak. ExApps voegt het tweede stuk toe: een productie-rijp patroon om wat dan ook, in welke taal dan ook, te draaien als ge\xefntegreerde app binnen de werkplek. Twee- tot driehonderdduizend servers. Enkele honderden apps in de store. ISO 27001. Blauer Engel. EU-data-hosting als standaard. Geen van deze beslissingen moet nog genomen worden. Ze zijn al uitgeleverd."}),"\n",(0,r.jsx)(n.p,{children:"De sovereign-workplace-beweging rond openDesk, Mijn Bureau, La Suite Num\xe9rique en het Bechtle-Nextcloud-aanbod gebruikt Nextcloud als kerncomponent. Schleswig-Holstein verhuisde in oktober 2025 40.000 ambtenaren weg van Microsoft, met openDesk als samenwerkingslaag. De Bundeswehr tekende een zevenjarig contract. Het Robert Koch Institut en het Internationaal Strafhof draaien erop. De uitrol is re\xebel en op schaal."}),"\n",(0,r.jsx)(n.p,{children:"Wat geen van die bundels (nog) doet, is Nextcloud framen als het platform onder de suite. Ze framen het als een van meerdere componenten in een bundel. Dat frame klopt voor het moment van overstappen van Microsoft. Het zal drie jaar later niet meer kloppen."}),"\n",(0,r.jsx)(n.h2,{id:"de-bundel-is-niet-de-werkplek",children:"De bundel is niet de werkplek"}),"\n",(0,r.jsx)(n.p,{children:'In jaar \xe9\xe9n vraagt een koper: "kan ik Microsoft vervangen?". In jaar drie vraagt diezelfde koper: "waar draait mijn organisatie eigenlijk?".'}),"\n",(0,r.jsx)(n.p,{children:"Een bundel beantwoordt de eerste vraag. Niet de tweede. Een bundel levert een vaste set tools, waarbij de integratie ertussen plaatsvindt in het hoofd van de gebruiker of in zijn browsertabs. Een werkplek is iets anders: het uniforme oppervlak waarop mensen werken, met het platform eronder dat al het andere host. Tools, data, AI, en de honderden kleine workflows die elke organisatie draait \u2014 te klein om door IT te laten formaliseren, te operationeel om uit te besteden. Verlofaanvragen. Materiaaluitleen. Bezoekersregistratie. Hardware-inventaris. Leveranciers-onboarding. De long tail."}),"\n",(0,r.jsx)(n.p,{children:"De leverancier die het antwoord op jaar drie geeft, wint de relatie. Nextcloud-als-bundel doet dat niet. Nextcloud-als-platform wel. Die herframing is wat naar mijn idee overdue is."}),"\n",(0,r.jsx)(n.h2,{id:"ai-als-substraat-niet-als-vinkje",children:"AI als substraat, niet als vinkje"}),"\n",(0,r.jsx)(n.p,{children:"AI verandert de rekensom rond lokale data \u2014 en niet in de richting die de meeste werkplek-leveranciers willen."}),"\n",(0,r.jsx)(n.p,{children:"Microsoft Copilot routeert gebruikersdata naar Azure voor inferentie. Google Workspace doet hetzelfde, naar Google Cloud. Beide hebben sovereign-cloud-varianten gebouwd \u2014 Bleu in Frankrijk via een joint venture van Capgemini en Orange, Delos in Duitsland via SAP en Telekom, Microsoft Cloud for Sovereignty als overkoepelend programma \u2014 en dat zijn serieuze engineering-trajecten. Ze verkleinen het blootstellingsoppervlak. Ze elimineren het niet. De CLOUD Act blijft van toepassing op Microsoft zelf, ook wanneer Europese partners de infrastructuur opereren. Het structurele probleem is jurisdictioneel, niet contractueel."}),"\n",(0,r.jsx)(n.p,{children:"Voor de meeste marksegmenten is de parti\xeble-soevereiniteit-pitch voldoende. Voor de kopers die specifiek voor openDesk en Mijn Bureau kozen omdat de architectuur ertoe doet, is dat niet zo. Die hebben het suite-pad om een reden gekozen."}),"\n",(0,r.jsx)(n.p,{children:"Een open werkplek-architectuur draait het probleem om. De data staat al op infrastructuur die de klant zelf beheert. Het AI-substraat komt naar de data toe, niet andersom. Lokale LLM-endpoints. Retrieval-indexering over de hele werkplek heen. Tools die registers blootstellen aan modellen binnen de sessie van de gebruiker, op elke stap audit-gelogd, met de operator die het model kiest. Mistral on-premise. Een self-hosted Llama-variant. Of, waar het beleid het toelaat, een commodity API. De architectuur ondersteunt de beleidskeuzes van de operator, niet die van de leverancier."}),"\n",(0,r.jsx)(n.p,{children:"De features zijn competitief. De architectuur is structureel anders. Dat structurele verschil komt in elke aanbestedingsevaluatie naar boven waar soevereiniteit serieus telt. Dit is het stuk waarop Nextclouds positie zich versterkt. Microsoft kan niet winnen op soevereiniteit voor de kopers die daar het meest om geven. Microsoft kan absoluut winnen op time-to-value en diepte van het ecosysteem \u2014 en dat is precies wat ze vijf jaar lang en met significant kapitaal proberen te doen. De race gaat over welk structureel voordeel zwaarder weegt voor welke koper."}),"\n",(0,r.jsx)(n.h2,{id:"de-microsoft-klok",children:"De Microsoft-klok"}),"\n",(0,r.jsx)(n.p,{children:'Even wat context over de omvang van de andere kant. Power Platform stond in 2023 op 33 miljoen monthly active users. 48 miljoen in 2024. 56 miljoen in 2025. Microsoft heeft 500 miljoen tegen het einde van het decennium genoemd als publiek doel. 97% van de Fortune 500-bedrijven gebruikt Power Platform in enige vorm. De 2026 release wave verenigt Power Apps, Power Automate, Power Pages, Copilot Studio en Dataverse tot \xe9\xe9n AI-native citizen-developer-verhaal. Intern gebruiken ze de framing "low code is dood": apps beginnen als gesprekken met Copilot en worden stilletjes React.'}),"\n",(0,r.jsx)(n.p,{children:"Europa heeft, naar mijn inschatting, ergens tussen de achttien en zesendertig maanden om een geloofwaardig architectonisch antwoord uit te leveren. Sluit dat venster eenmaal, dan zijn citizen developers in Europese organisaties getraind op de Microsoft-stack, en switching costs worden re\xebel op een manier die geen sales motion meer oplost. Mindshare is het belangrijkste venster. Het sluit ook het snelst."}),"\n",(0,r.jsx)(n.h2,{id:"wat-waar-moet-zijn",children:"Wat waar moet zijn"}),"\n",(0,r.jsxs)(n.p,{children:["Het architectonische antwoord bestaat in stukken. De sovereign-workplace-bundels zijn \xe9\xe9n stuk. Open-source workflow-tools \u2014 Windmill, n8n, OpenProject \u2014 zijn een tweede. Open-weight LLM's gehost in Europa zijn een derde. De compositie-laag waarmee een niet-ontwikkelaar in een gemeente in \xe9\xe9n middag een verlofaanvraag-app live krijgt, is het stuk dat in productie nog grotendeels ontbreekt. Dat is het stuk dat wij bij Conduction bouwen, in de openbaarheid, als ",(0,r.jsx)(n.a,{href:"/apps/openbuild",children:"OpenBuild"}),". Het is niet het enige stuk dat geleverd moet worden. Het is er \xe9\xe9n."]}),"\n",(0,r.jsx)(n.p,{children:"Het andere dat waar moet zijn, is naamgeving. Steve Jobs verkocht de iPhone niet als een telefoon met uitbreidbare features. Hij positioneerde hem als het platform dat apps draait, jaren voordat die platformrealiteit volledig was geleverd. De naamgeving was dragend. Dat is ze nog steeds."}),"\n",(0,r.jsx)(n.p,{children:"Nextcloud-als-platform is vandaag al waar in elke structurele zin die ertoe doet. Wat ontbreekt, is dat het bedrijf, het ecosysteem en de kopers het ook zo gaan uitspreken."}),"\n",(0,r.jsx)(n.h2,{id:"een-persoonlijke-noot",children:"Een persoonlijke noot"}),"\n",(0,r.jsx)(n.p,{children:"Ik heb vier kwartalen runway van mijn bedrijf gestoken in het bouwen naar deze visie. Het is geen rustige visie. Ik schrijf het op omdat ik denk dat het architectonische argument beslecht is, het competitieve venster open staat, en de volgende zet toebehoort aan mensen die de vorm van het moment helder kunnen zien. Daaronder valt het team van Nextcloud. Daaronder vallen de kopers die Europese sovereign-workplace-migraties draaien. Daaronder vallen collega-bedrijven in de open-source workplace-stack."}),"\n",(0,r.jsxs)(n.p,{children:["Lees je dit en ben je het oneens \u2014 dan hoor ik graag waarom. ",(0,r.jsx)(n.a,{href:"mailto:ruben@conduction.nl",children:"ruben@conduction.nl"}),"."]})]})}function u(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(p,{...e})}):p(e)}},94474(e){e.exports=JSON.parse('{"permalink":"/nl/academy/the-platform-moment","source":"@site/i18n/nl/docusaurus-plugin-content-blog/2026-05-19-the-platform-moment/index.mdx","title":"Nextcloud is een platform","description":"Hetzelfde patroon duikt op elke keer dat een softwarecategorie door zijn platformmoment heen gaat. WordPress in 2011. Salesforce een paar jaar eerder. Atlassian daarna. De iPhone, in de consumentenmarkt, v\xf3\xf3r allemaal. Elk van hen begon als product. Elk werd een platform. De bedrijven die de overgang goed managen, bezitten hun categorie twee decennia later. De bedrijven die dat niet deden, zijn voetnoten.","date":"2026-05-19T00:00:00.000Z","tags":[{"inline":true,"label":"Nextcloud","permalink":"/nl/academy/tags/nextcloud"},{"inline":true,"label":"Platform","permalink":"/nl/academy/tags/platform"},{"inline":true,"label":"Sovereignty","permalink":"/nl/academy/tags/sovereignty"},{"inline":true,"label":"AI","permalink":"/nl/academy/tags/ai"}],"readingTime":7.27,"hasTruncateMarker":true,"authors":[{"name":"Ruben van der Linde","title":"CTO, Conduction","url":"https://github.com/rubenvdlinde","page":{"permalink":"/nl/academy/authors/ruben"},"socials":{"github":"https://github.com/rubenvdlinde","email":"mailto:ruben@conduction.nl"},"imageURL":"https://github.com/rubenvdlinde.png","key":"ruben"}],"frontMatter":{"slug":"the-platform-moment","title":"Nextcloud is een platform","contentType":"opinion","authors":["ruben"],"date":"2026-05-19T00:00:00.000Z","summary":"Een opiniestuk over waarom Nextcloud bekeken zou moeten worden als een platform, niet als een product. De sovereign-workplace-bundels zijn het begin, niet het einde. Microsoft heeft achttien tot zesendertig maanden. Europa ook.","tags":["Nextcloud","Platform","Sovereignty","AI"],"durationMinutes":7},"unlisted":false,"prevItem":{"title":"OpenWoo-community \u2014 twee jaar maandelijkse meetings","permalink":"/nl/academy/openwoo-community-meetings"},"nextItem":{"title":"Build a Nextcloud app on the Conduction stack \u2014 Part 4: Knowledge + ship","permalink":"/nl/academy/build-an-app-tutorial-4-knowledge-and-ship"}}')}}]);